n = int(input())
prices = list(map(int, input().split()))
for i in range(n):
    smallest = i
    for j in range(i + 1, n):
        if prices[j] < prices[smallest]:
            smallest = j
    prices[i], prices[smallest] = prices[smallest], prices[i]
print(" ".join(map(str, prices)))

t = int(input())
caps = list(map(int, input().split()))
n = int(input())
weights = list(map(int, input().split()))
loads = []
left = []
for cap in caps:
    loads.append([])
    left.append(cap)
dock = []
for w in weights:
    placed = False
    for i in range(t):
        if left[i] >= w:
            loads[i].append(w)
            left[i] -= w
            placed = True
            break
    if not placed:
        dock.append(w)
for i in range(t):
    joined = " ".join(map(str, loads[i]))
    if joined:
        print(f"Truck {i + 1}: {joined} | left: {left[i]}")
    else:
        print(f"Truck {i + 1}: | left: {left[i]}")
if dock:
    print("Dock: " + " ".join(map(str, dock)))
else:
    print("Dock:")

n = int(input())
seats = [input() for _ in range(n)]
m = int(input())
for _ in range(m):
    parts = input().split()
    op = parts[0]
    if op == "JOIN":
        seats.insert(int(parts[1]), parts[2])
    elif op == "LEAVE":
        seats.pop(int(parts[1]))
    elif op == "MOVE":
        a, b = int(parts[1]), int(parts[2])
        student = seats.pop(a)
        seats.insert(b, student)
    else:
        p, q = int(parts[1]), int(parts[2])
        seats[p], seats[q] = seats[q], seats[p]
for name in seats:
    print(name)

